function updatePrice(e){document.querySelector(".cur-price").innerText=e}function checkVersion(e,n,r,o){let t=e.currentTarget.innerText;let c;const i=document.querySelector(n);const u=i.querySelectorAll(".option-item");for(let e=0;e<u.length;e++){if(u[e].classList.contains("active")){c=u[e].innerText}}checkVersionAjax(r,o,t,c)}function checkVersionAjax(e,n,r,o){$.ajax({type:"GET",url:"product?action=checkVersion",data:{productID:e,kind:n,version:r,other:o},success:function(e){$("#productDetail-response").html(e)},error:function(e){console.error("Error during querying: ",e)}})}function addToCart(){var e=document.querySelector('input[name="chosen-detailID"]').value;if(e==""){showInfoToast2("Hãy chọn phân loại!","none");return}$.ajax({type:"POST",url:"cart?a=add",data:{id:e},success:function(e){$("#productDetail-response").html(e)},error:function(e){console.error("Error during querying: ",e)}})}function buy(e){e.preventDefault();var n=document.querySelector('input[name="chosen-detailID"]').value;if(n==""){showInfoToast2("Hãy chọn phân loại!","none");return}var r=e.currentTarget.href+"&id="+n;window.location.href=r}function checkClassify(e){document.querySelector('input[name="chosen-detailID"]').value=e;$.ajax({type:"POST",url:"product?a=classify",data:{id:e},success:function(e){console.log(e);$("#productDetail-response").html(e)},error:function(e){console.error("Error during querying: ",e)}})}function updatePrice(e,n){const r=document.querySelectorAll(".cur-price");r.forEach((function(n){n.innerText=e}));const o=document.querySelectorAll(".pre-price");o.forEach((function(e){e.innerText=n}))}